<template id="jz-iconos-ui">@foreach(['save', 'check', 'circle-check', 'circle-x', 'triangle-alert', 'camera', 'image', 'star', 'smartphone', 'lightbulb', 'cake', 'globe', 'arrow-left', 'arrow-right', 'fingerprint', 'bell', 'user-round', 'shield-check', 'paperclip', 'download', 'upload', 'file-text', 'rotate-cw', 'undo-2'] as $ic)<span data-icon="{{ $ic }}"><x-icono :name="$ic" /></span>@endforeach</template>
<script>window.jzIcono=function(name,classes){const source=document.getElementById('jz-iconos-ui').content.querySelector('[data-icon="'+String(name).replace(/[^a-z0-9-]/g,'')+'"] svg');if(!source)return '';const svg=source.cloneNode(true);if(classes)svg.setAttribute('class','jz-icon '+classes);return svg.outerHTML;};</script>
